### Test Harness

`test/harness.html` loads the Module Bundle via dynamic `import()` — no `<script>` tag injection:

```html
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Harness: member-search</title></head>
<body>
  <div id="root"></div>
  <script type="module">
    import React from 'react';
    import ReactDOM from 'react-dom/client';
    const { get, init } = await import('./dist/mf/remoteEntry.js');
    await init({ react: { get: () => Promise.resolve(React) }, 'react-dom': { get: () => Promise.resolve(ReactDOM) } });
    const factory = await get('./MemberSearch');
    const { MemberSearch } = factory();
    ReactDOM.createRoot(document.getElementById('root')).render(React.createElement(MemberSearch));
  </script>
</body>
</html>
```

